  # Jackson, Michigan county
  OPTIONAL {
    FILTER (?answerJackson != ns:m.042tq)
    ns:m.042tq ns:location.hud_county_place.county ?answerJackson .
  }
  # Minneapolis, MN county
  OPTIONAL {
    FILTER (?answerMinneapolis != ns:m.0fpzwf)
    ns:m.0fpzwf ns:location.hud_county_place.county ?answerMinneapolis .
  }
  # State bird and flower of Michigan
  OPTIONAL {
    ns:m.04rrx ns:government.governmental_jurisdiction.official_symbols ?symRel . # Michigan
    ?symRel ns:location.location_symbol_relationship.symbol ?symbol .
    ?symRel ns:location.location_symbol_relationship.Kind_of_symbol ?type .
