```PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT ?war ?position ?vp
WHERE {
  {
    SELECT DISTINCT ?war
    WHERE
    { 
      {
        SELECT ?pfrom ?pto
        WHERE {
          ns:m.04jt2 ns:government.politician.government_positions_held ?pos .
          ?pos ns:government.government_position_held.basic_title ns:m.060c4 ;  # President
               ns:government.government_position_held.from ?pfrom ;
               ns:government.government_position_held.to ?pto .
        }
      }
      {
        SELECT ?from ?to ?war
        WHERE {
          ?war ns:common.topic.notable_types ns:m.02h76fz . # Military Conflict
          ?war ns:time.event.start_date ?from .
          ?war ns:time.event.end_date ?to .
          ?war ns:military.military_conflict.combatants ?combatant .
          ?combatant ns:military.military_combatant_group.combatants ns:m.09c7w0 . # United States
        }
      }
      FILTER (?to <= ?pto && ?from >= ?pfrom)
    }
  }
  {
    SELECT DISTINCT ?position
    WHERE {
      ns:m.04jt2 ns:government.politician.government_positions_held ?pos .
      ?pos ns:government.government_position_held.office_position_or_title ?position .
    }
  }
  OPTIONAL {
    ns:m.04jt2 ns:government.us_president.vice_president ?vp .
  }
}
LIMIT 1
```

