PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?war ?birthPlace ?electionYear
WHERE {
  # During what war did Abraham Lincoln serve as president?
  {
    SELECT ?fromPresident ?toPresident
    WHERE {
      ns:m.0gzh ns:government.politician.government_positions_held ?pos .
      ?pos ns:government.government_position_held.basic_title ns:m.060c4 ; # President
           ns:government.government_position_held.from ?fromPresident ;
           ns:government.government_position_held.to ?toPresident .
    }
  }
  {
    SELECT ?war ?startWar ?endWar
    WHERE {
      ?war ns:common.topic.notable_types ns:m.02h76fz . # Military Conflict
      ?war ns:time.event.start_date ?startWar .
      ?war ns:time.event.end_date ?endWar .
      ?war ns:military.military_conflict.combatants ?combatant .
      ?combatant ns:military.military_combatant_group.combatants ns:m.09c7w0 . # United States of America
    }
  }
  FILTER(?startWar <= ?toPresident && ?endWar >= ?fromPresident)

  # What town was Abe Lincoln born in?
  OPTIONAL {
    ns:m.0gzh ns:people.person.place_of_birth ?birthPlace .
    ?birthPlace ns:common.topic.notable_types ns:m.01m9 . # Town
  }

  # When was President Lincoln elected?
  OPTIONAL {
    ?election ns:government.election.winner ns:m.0gzh ;
              ns:government.election.office ns:m.060d2 ; # President of the United States
              ns:government.election.election_year ?electionYear .
  }
}
