PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?state ?war ?illness
WHERE {
  # State George Washington lived in
  OPTIONAL {
    ns:m.034rd ns:people.person.places_lived ?placeLived .
    ?placeLived ns:people.place_lived.location ?location .
    ?location ns:location.location.containedby ?state .
    ?state ns:common.topic.notable_types ns:m.0kpys4 .  # US State
  }
  # War during Woodrow Wilson presidency
  OPTIONAL {
    {
      SELECT ?pfrom ?pto
      WHERE {
        ns:m.083q7 ns:government.politician.government_positions_held ?pos .  # Woodrow Wilson
        ?pos ns:government.government_position_held.basic_title ns:m.060c4 ;  # President
             ns:government.government_position_held.from ?pfrom ;
             ns:government.government_position_held.to ?pto .
      }
    }
    {
      SELECT ?wfrom ?wto ?war
      WHERE {
        ?war ns:common.topic.notable_types ns:m.02h76fz . # Military Conflict
        ?war ns:time.event.start_date ?wfrom .
        ?war ns:time.event.end_date ?wto .
        ?war ns:military.military_conflict.combatants ?combatant .
        ?combatant ns:military.military_combatant_group.combatants ns:m.09c7w0 .  # USA
      }
    }
    FILTER (?wto <= ?pto && ?wfrom >= ?pfrom)
  }
  # Illnesses George Washington suffered from
