    FILTER (?illness != ns:m.034rd)
    FILTER (!isLiteral(?illness) || lang(?illness) = '' || langMatches(lang(?illness), 'en'))
    ns:m.034rd ns:medicine.notable_person_with_medical_condition.condition ?illness .
