  {
    {
      SELECT ?province (MAX(?yr) AS ?recent_yr)
      WHERE {
        ns:m.0d060g ns:location.location.contains ?province .
        ?province ns:common.topic.notable_types ns:m.01nm .
        ?province ns:location.statistical_region.population ?pop .
        ?pop ns:measurement_unit.dated_integer.number ?popNum .
        ?pop ns:measurement_unit.dated_integer.year ?yr .
      }
      GROUP BY ?province
    }
    {
      SELECT ?province ?popNum ?yr
      WHERE {
        ns:m.0d060g ns:location.location.contains ?province .
        ?province ns:common.topic.notable_types ns:m.01nm .
        ?province ns:location.statistical_region.population ?pop .
        ?pop ns:measurement_unit.dated_integer.number ?popNum .
        ?pop ns:measurement_unit.dated_integer.year ?yr .
