```PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?owner
WHERE {
  VALUES ?company { ns:m.01_bp ns:m.01_bp ns:m.05b4c }

  {
    # Query for "who owns the chrysler corporation?" (board members as owners)
    FILTER (?company = ns:m.01_bp)
    ?company ns:organization.organization.board_members ?boardMembership .
    ?boardMembership ns:organization.organization_board_membership.member ?owner .
  } UNION {
    # Query for "who owns chrysler corporation 2012?" (parent organizations in 2012)
    FILTER (?company = ns:m.01_bp)
    ?rel ns:organization.organization_relationship.child ?company .
    ?rel ns:organization.organization_relationship.parent ?owner .
    FILTER (
      (
        NOT EXISTS { ?rel ns:organization.organization_relationship.to ?toDate } 
        || EXISTS { ?rel ns:organization.organization_relationship.to ?toDate . FILTER(xsd:dateTime(?toDate) >= "2012-01-01T00:00:00Z"^^xsd:dateTime) }
      ) && 
      (
        NOT EXISTS { ?rel ns:organization.organization_relationship.from ?fromDate } 
        || EXISTS { ?rel ns:organization.organization_relationship.from ?fromDate . FILTER(xsd:dateTime(?fromDate) <= "2012-12-31T23:59:59Z"^^xsd:dateTime) }
      )
    )
  } UNION {
    # Query for "who owns nissan car manufacturer?" (founders as owners)
    FILTER (?company = ns:m.05b4c)
    ?company ns:organization.organization.founders ?owner .
  }
  FILTER (?owner != ?company)
  FILTER (!isLiteral(?owner) || lang(?owner) = '' || langMatches(lang(?owner), 'en'))
}
