PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?x
WHERE {
  {
    # who succeeded William McKinley as president?
    ns:m.060d2 ns:government.government_office_or_title.office_holders ?y1 .
    ?y1 ns:government.government_position_held.office_holder ns:m.083p7 ;
        ns:government.government_position_held.to ?to .
    ns:m.060d2 ns:government.government_office_or_title.office_holders ?y2 .
    ?y2 ns:government.government_position_held.office_holder ?x ;
        ns:government.government_position_held.from ?from .
