  }
  UNION
  {
    # who was the president of the United States during WW2?
    ns:m.081pw ns:time.event.start_date ?start ;
               ns:time.event.end_date ?end .
    ?x ns:government.politician.government_positions_held ?y .
    ?y ns:government.government_position_held.office_position_or_title ns:m.060d2 ;
       ns:government.government_position_held.from ?from ;
       ns:government.government_position_held.to ?to .
    FILTER(?from < ?end && ?to > ?start)
  }
  UNION
  {
    # who became president when Roosevelt died in office?
    ns:m.060d2 ns:government.government_office_or_title.office_holders ?y1 .
    ?y1 ns:government.government_position_held.office_holder ns:m.02yy8 ;
        ns:government.government_position_held.to ?to .
    ns:m.060d2 ns:government.government_office_or_title.office_holders ?y2 .
    ?y2 ns:government.government_position_held.office_holder ?x ;
        ns:government.government_position_held.from ?from .
    FILTER(xsd:dateTime(?from) > xsd:dateTime(?to))
  }
}
ORDER BY ?x
LIMIT 1
