```sparql
PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?became_president ?before_president ?vroose_vice_president WHERE {
  {
    # Who became president when Franklin D. Roosevelt died in office?
    ns:m.060d2 ns:government.government_office_or_title.office_holders ?pos1 .  # President of the United States
    ?pos1 ns:government.government_position_held.office_holder ns:m.02yy8 ;
          ns:government.government_position_held.to ?to .
    ns:m.060d2 ns:government.government_office_or_title.office_holders ?pos2 .
    ?pos2 ns:government.government_position_held.office_holder ?became_president ;
          ns:government.government_position_held.from ?from .
    FILTER(xsd:dateTime(?from) > xsd:dateTime(?to))
  }
  {
    # What did Abraham Lincoln do before he was president?
    SELECT ?before_president WHERE {
      {
        SELECT ?lincoln_pres_from WHERE {
          ns:m.0gzh ns:government.politician.government_positions_held ?pos_pres .
          ?pos_pres ns:government.government_position_held.office_position_or_title ?office ;
                    ns:government.government_position_held.basic_title ns:m.060c4 ; # President
                    ns:government.government_position_held.from ?lincoln_pres_from .
        }
      }
      ns:m.0gzh ns:government.politician.government_positions_held ?pos_before .
      ?pos_before ns:government.government_position_held.office_position_or_title ?before_president ;
                  ns:government.government_position_held.from ?from_before .
      FILTER(xsd:dateTime(?from_before) < xsd:dateTime(?lincoln_pres_from))
    }
  }
  {
    # Who was Theodore Roosevelt's vice president?
    ns:m.07hyk ns:government.us_president.vice_president ?vroose_vice_president .
  }
}
LIMIT 1
```

