  {
    # who has won the most fa cup?
    {
      SELECT ?x (COUNT(?x) as ?count)
      WHERE {
        ns:m.02_p0 ns:sports.sports_award_type.winners ?y2 .
        ?y2 ns:sports.sports_award.award_winner ?x .
      }
      GROUP BY ?x
    }
    {
      SELECT (MAX(?count) AS ?maxCount)
      WHERE {
        {
          SELECT ?x (COUNT(?x) as ?count)
          WHERE {
            ns:m.02_p0 ns:sports.sports_award_type.winners ?y3 .
            ?y3 ns:sports.sports_award.award_winner ?x .
          }
          GROUP BY ?x
        }
      }
    }
    FILTER (?count = ?maxCount)
  }
  UNION
  {
    # who won the fa cup in 2008?
    ns:m.02_p0 ns:sports.sports_award_type.winners ?y4 .
    ?y4 ns:sports.sports_award.award_winner ?x .
